/* @autogenerated */
package net.civeira.phylax.feature.observe.anomaly;

import java.nio.file.Path;
import java.util.ArrayList;
import java.util.List;
import java.util.Map;

import org.junit.jupiter.api.Assertions;
import org.junit.jupiter.api.DisplayName;
import org.junit.jupiter.api.Test;
import org.junit.jupiter.api.io.TempDir;

import net.civeira.phylax.feature.observe.metric.Histogram;
import net.civeira.phylax.feature.observe.metric.MetricDeriver;
import net.civeira.phylax.feature.observe.metric.MetricPoint;
import net.civeira.phylax.feature.observe.store.ObsLog;

class AnomalyUnitTest {

  private static final long HOUR = MetricDeriver.HOUR;
  /** A Monday 10:00 UTC. */
  private static final long MONDAY_10 =
      java.time.Instant.parse("2026-11-09T10:00:00Z").toEpochMilli();

  @TempDir
  Path dir;

  private static MetricPoint point(final long ts, final long step, final long count,
      final long errors) {
    Histogram histogram = new Histogram();
    for (int i = 0; i < Math.min(count, 50); i++) {
      histogram.add(40);
    }
    return new MetricPoint(ts, step, "api", "/orders", "GET", count, errors, 0, histogram.counts());
  }

  /**
   * Four weeks of Mondays at 10:00 with about 600 requests per hour (10 per minute) and 1 % errors.
   */
  private static Baselines history() {
    List<MetricPoint> points = new ArrayList<>();
    for (int week = 1; week <= 4; week++) {
      points.add(point(MONDAY_10 - week * 7 * 24 * HOUR, HOUR, 580 + week * 10, 6));
    }
    return Baselines.of(points);
  }

  @Test
  @DisplayName("A spike of errors far from the usual for that hour is an anomaly; the usual is not")
  void detect() {
    AnomalyDetector detector = new AnomalyDetector(3, 20);
    List<MetricPoint> normal = List.of(point(MONDAY_10 + 60_000, 60_000, 150, 1));
    Assertions
        .assertTrue(detector.detect(history(), normal, 15, MONDAY_10 + 15 * 60_000).isEmpty());
    List<MetricPoint> errors = List.of(point(MONDAY_10 + 60_000, 60_000, 150, 60));
    List<AnomalyDetector.Anomaly> found =
        detector.detect(history(), errors, 15, MONDAY_10 + 15 * 60_000);
    Assertions.assertTrue(found.stream()
        .anyMatch(a -> a.metric().equals(Baselines.ERRORS) && a.direction().equals("up")));
    List<MetricPoint> few = List.of(point(MONDAY_10 + 60_000, 60_000, 5, 5));
    Assertions.assertTrue(detector.detect(history(), few, 15, MONDAY_10 + 15 * 60_000).isEmpty());
  }

  @Test
  @DisplayName("Weekday and weekend hours are different slots")
  void slots() {
    Assertions.assertEquals(10, Baselines.slot(MONDAY_10));
    Assertions.assertEquals(34, Baselines.slot(MONDAY_10 - 2 * 24 * HOUR));
  }

  @Test
  @DisplayName("A new WARN template is a new pattern once; after a restart it is known")
  void patterns() {
    LogPatterns patterns = new LogPatterns(dir);
    ObsLog warn = new ObsLog(1_000, "api", "WARN", "x", "Pool exhausted after 30 ms for order 1234",
        null, null, null, Map.of(), null, null);
    ObsLog same = new ObsLog(2_000, "api", "WARN", "x", "Pool exhausted after 45 ms for order 99",
        null, null, null, Map.of(), null, null);
    ObsLog info =
        new ObsLog(3_000, "api", "INFO", "x", "Started", null, null, null, Map.of(), null, null);
    patterns.observe(List.of(warn, same, info));
    List<LogPatterns.Pattern> found = patterns.since(0);
    Assertions.assertEquals(1, found.size());
    Assertions.assertEquals(2, found.get(0).count());
    LogPatterns restarted = new LogPatterns(dir);
    restarted.load();
    restarted.observe(List.of(same));
    Assertions.assertEquals(1, restarted.since(0).size());
    Assertions.assertTrue(restarted.since(1_500).isEmpty());
  }
}
